## Physics Simulation

```cpp
// Apply force to rigid body
void ApplyExplosionForce(FVector location, float force) {
    TArray<AActor*> actors;
    GetAllActors(actors);

    for (AActor* actor : actors) {
        float distance = (actor->GetLocation() - location).Size();
        if (distance < ExplosionRadius) {
            FVector direction = (actor->GetLocation() - location).GetSafeNormal();
            float forceMagnitude = force * (1.0f - distance / ExplosionRadius);
            actor->AddImpulse(direction * forceMagnitude);
        }
    }
}
```

